def solve(g):
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    mk=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v!=bg]
    r0,r1=min(i for i,j in mk),max(i for i,j in mk); c0,c1=min(j for i,j in mk),max(j for i,j in mk)
    o=[r[:] for r in g]
    for j in range(c0,c1+1):
        if o[r0][j]==bg: o[r0][j]=2
        if o[r1][j]==bg: o[r1][j]=2
    for i in range(r0,r1+1):
        if o[i][c0]==bg: o[i][c0]=2
        if o[i][c1]==bg: o[i][c1]=2
    rl={i for i in range(r0,r1+1) if sum(1 for j in range(c0+1,c1) if g[i][j]!=bg)>=2}
    cl={j for j in range(c0,c1+1) if sum(1 for i in range(r0+1,r1) if g[i][j]!=bg)>=2}
    for i in rl:
        for j in range(c0,c1+1):
            if o[i][j]==bg: o[i][j]=2
    for j in cl:
        for i in range(r0,r1+1):
            if o[i][j]==bg: o[i][j]=2
    return o
